<script type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"ProfessionalService","@id":"https://newhampshireinsuranceappraiser.com/#business","name":"New Hampshire Insurance Appraiser","url":"https://newhampshireinsuranceappraiser.com/","telephone":"+1 (844) 537-1427","email":"info@newhampshireinsuranceappraiser.com","logo":{"@type":"ImageObject","@id":"https://newhampshireinsuranceappraiser.com/#logo","url":"https://newhampshireinsuranceappraiser.com/favicon-512.png","contentUrl":"https://newhampshireinsuranceappraiser.com/favicon-512.png","width":512,"height":512,"caption":"New Hampshire Insurance Appraiser"},"image":{"@id":"https://newhampshireinsuranceappraiser.com/#logo"},"address":{"@type":"PostalAddress","addressRegion":"NH","addressCountry":"US"},"contactPoint":[{"@type":"ContactPoint","telephone":"+1 (844) 537-1427","email":"info@newhampshireinsuranceappraiser.com","contactType":"customer service","areaServed":"US-NH","availableLanguage":"en"}],"slogan":"Independent appraisal for property claims that came up short","description":"Independent insurance appraisal, estimate review and umpire services for disputed property claims across New Hampshire.","areaServed":[{"@type":"State","name":"New Hampshire"},{"@type":"City","name":"Manchester"},{"@type":"City","name":"Nashua"},{"@type":"City","name":"Concord"},{"@type":"City","name":"Portsmouth"},{"@type":"City","name":"Dover"},{"@type":"City","name":"Rochester"},{"@type":"City","name":"Derry"},{"@type":"City","name":"Salem"},{"@type":"City","name":"Keene"},{"@type":"City","name":"Laconia"},{"@type":"City","name":"Lebanon"},{"@type":"City","name":"Hanover"},{"@type":"City","name":"North Conway"}],"hasOfferCatalog":{"@type":"OfferCatalog","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Policyholder’s Appraiser on the Panel","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/appraisal-clause-representation-nh/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Single-Family Home Claims","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/homeowners-claim-appraisal-nh/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Condo, Association & Business Claims","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/nh-commercial-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof Damage & Hail Disputes","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/roof-and-hail-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Microburst & Windstorm Losses","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/wind-microburst-tornado-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tropical Remnants & Coastal Storms","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/tropical-storm-hurricane-appraisal-nh/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Frozen Pipe & Leak Claims","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/pipe-burst-water-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Chimney, Fire & Smoke Losses","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/fire-smoke-soot-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Dams & Heavy Roof Snow","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/ice-dam-roof-snow-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Trees Down on the Property","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/falling-tree-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Line-by-Line Estimate Audit","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/insurer-estimate-audit/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Neutral Umpire Appointments","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/appraisal-umpire-nh/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Ice dam claims","Roof snow load","Umpire services"],"priceRange":"$$","openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://newhampshireinsuranceappraiser.com/#website","url":"https://newhampshireinsuranceappraiser.com/","name":"New Hampshire Insurance Appraiser","publisher":{"@id":"https://newhampshireinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://newhampshireinsuranceappraiser.com/nh-appraisal-faq/#webpage","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-faq/","name":"Insurance Appraisal FAQ | New Hampshire Owners","description":"Insurance appraisal FAQ for New Hampshire owners: how the process works, what it costs, timing, deadlines and when an award is binding.","inLanguage":"en-US","isPartOf":{"@id":"https://newhampshireinsuranceappraiser.com/#website"},"about":{"@id":"https://newhampshireinsuranceappraiser.com/#business"},"publisher":{"@id":"https://newhampshireinsuranceappraiser.com/#business"},"dateModified":"2026-11-14","primaryImageOfPage":{"@type":"ImageObject","@id":"https://newhampshireinsuranceappraiser.com/nh-appraisal-faq/#primaryimage","url":"https://newhampshireinsuranceappraiser.com/assets/img/photos/consult-laptop.webp","width":960,"height":640},"breadcrumb":{"@id":"https://newhampshireinsuranceappraiser.com/nh-appraisal-faq/#breadcrumb"},"mainEntity":{"@id":"https://newhampshireinsuranceappraiser.com/nh-appraisal-faq/#faq"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://newhampshireinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal FAQ","item":"https://newhampshireinsuranceappraiser.com/nh-appraisal-faq/"}],"@id":"https://newhampshireinsuranceappraiser.com/nh-appraisal-faq/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is insurance appraisal, in plain terms?","acceptedAnswer":{"@type":"Answer","text":"It’s a process written into most property policies for settling a disagreement about the dollar amount of a covered loss. Each side names an appraiser, the two pick an umpire, and any two of the three can sign a binding figure."}},{"@type":"Question","name":"When does appraisal make sense?","acceptedAnswer":{"@type":"Answer","text":"When the insurer agrees the damage is covered but you disagree on what it costs to fix, and the gap is meaningful. If the argument is about whether something is covered at all, appraisal usually isn’t the right tool."}},{"@type":"Question","name":"Can I demand appraisal if my whole claim was denied?","acceptedAnswer":{"@type":"Answer","text":"Usually not on its own, because a full denial is a coverage dispute rather than a disagreement about amount. Talk to a New Hampshire attorney about a denial; appraisal may come later if coverage is accepted."}},{"@type":"Question","name":"Does the insurer have to agree to appraisal?","acceptedAnswer":{"@type":"Answer","text":"Under most appraisal clauses either side can demand it in writing, and the other side is expected to take part. Insurers sometimes object on coverage or procedural grounds, which is a legal question for an attorney."}},{"@type":"Question","name":"Do I need my own estimate before demanding appraisal?","acceptedAnswer":{"@type":"Answer","text":"It helps a great deal. A contractor’s estimate or an independent estimate review shows where the gap is and whether it is large enough to justify the cost of appraisal."}},{"@type":"Question","name":"How are appraisers paid?","acceptedAnswer":{"@type":"Answer","text":"Each side pays its own appraiser. Arrangements vary — hourly, flat fee or a percentage of the award — so get the terms in writing before you sign."}},{"@type":"Question","name":"Who pays the umpire?","acceptedAnswer":{"@type":"Answer","text":"Most appraisal clauses split the umpire’s fees and expenses equally between you and the insurer. Check your policy for its exact wording."}},{"@type":"Question","name":"Is appraisal worth it on a small gap?","acceptedAnswer":{"@type":"Answer","text":"Often not. When the difference is a few thousand dollars, appraiser and umpire fees can absorb much of it, so run the numbers first."}},{"@type":"Question","name":"Can the award come in lower than the insurer’s estimate?","acceptedAnswer":{"@type":"Answer","text":"It can. The panel values the loss independently and isn’t bound by either side’s number, which is one reason to start with an honest, well-supported estimate."}},{"@type":"Question","name":"Does the award account for my deductible and depreciation?","acceptedAnswer":{"@type":"Answer","text":"The award normally sets the amount of loss, often broken into replacement cost, depreciation and actual cash value. The insurer then applies the deductible, earlier payments and policy limits when it pays."}},{"@type":"Question","name":"How long does an appraisal take in New Hampshire?","acceptedAnswer":{"@type":"Answer","text":"Straightforward residential appraisals often wrap up within a few months. Snow cover, scheduling, large commercial losses and umpire involvement can stretch that out."}},{"@type":"Question","name":"Is there a deadline to demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Some policies set one and many don’t, but courts can look at whether a demand came within a reasonable time. Don’t sit on a dispute; check your policy and ask an attorney if the timing is tight."}},{"@type":"Question","name":"Does appraisal pause the suit-limitation period?","acceptedAnswer":{"@type":"Answer","text":"Not necessarily. Many policies set a contractual window to sue and appraisal may not stop it, so check your policy and talk to a New Hampshire attorney before the date gets close."}},{"@type":"Question","name":"Can winter hold up the inspection?","acceptedAnswer":{"@type":"Answer","text":"Yes. Deep snow can hide roof and siding damage, so appraisers sometimes inspect what they can and return after the thaw to measure the rest."}},{"@type":"Question","name":"How soon does the insurer pay after an award?","acceptedAnswer":{"@type":"Answer","text":"Payment timing depends on the policy and the insurer’s process, and many forms state a period after the award is filed. Recoverable depreciation is often paid later, once repairs are documented."}},{"@type":"Question","name":"Who do you represent?","acceptedAnswer":{"@type":"Answer","text":"When we’re appointed as your appraiser, you retain us and we prepare the valuation on your claim. On separate claims we may serve as a neutral umpire, where we represent neither side."}},{"@type":"Question","name":"Are you a public adjuster or a law firm?","acceptedAnswer":{"@type":"Answer","text":"Neither. New Hampshire Insurance Appraiser handles appraisal-clause work, estimate reviews and umpire assignments; we don’t give legal advice or adjust claims outside appraisal."}},{"@type":"Question","name":"What should I send for a first review?","acceptedAnswer":{"@type":"Answer","text":"Your declarations page, the full policy if you have it, the insurer’s complete estimate, any letters from the insurer, photos and your contractor’s estimate."}},{"@type":"Question","name":"Do you work across the whole state?","acceptedAnswer":{"@type":"Answer","text":"Yes. We take claims in all ten counties, from the Seacoast and the Merrimack Valley to the Lakes Region and the Great North Woods."}},{"@type":"Question","name":"Can you be the umpire on a claim where you’re my appraiser?","acceptedAnswer":{"@type":"Answer","text":"No. An umpire has to be neutral, so a firm acting as your appraiser can’t also be the umpire on that claim."}},{"@type":"Question","name":"Who regulates insurance companies in New Hampshire?","acceptedAnswer":{"@type":"Answer","text":"The New Hampshire Insurance Department in Concord, led by the Insurance Commissioner. It accepts consumer complaints and inquiries about insurers doing business in the state."}},{"@type":"Question","name":"Does New Hampshire have a bad-faith penalty statute?","acceptedAnswer":{"@type":"Answer","text":"New Hampshire doesn’t have a broad first-party bad-faith penalty statute; remedies depend on the policy, contract law and the facts. Ask a New Hampshire attorney about your situation."}},{"@type":"Question","name":"What does RSA chapter 417 cover?","acceptedAnswer":{"@type":"Answer","text":"It addresses unfair insurance trade practices, including unfair claim settlement practices such as misrepresenting policy provisions. Enforcement is largely administrative through the Insurance Department; whether you have a private claim is a question for an attorney."}},{"@type":"Question","name":"Who appoints the umpire if the appraisers can’t agree?","acceptedAnswer":{"@type":"Answer","text":"Many policies say a court of record where the property is located may appoint one. In New Hampshire that is generally the Superior Court in the county where the property sits."}},{"@type":"Question","name":"Does a New Hampshire FAIR Plan policy include appraisal?","acceptedAnswer":{"@type":"Answer","text":"Many property forms do, but check the FAIR Plan policy you hold for its own appraisal wording and conditions."}}],"@id":"https://newhampshireinsuranceappraiser.com/nh-appraisal-faq/#faq"}]}</script>
</head>
